"use client";

import { useEffect, useState } from "react";
import { apiGet } from "@/lib/api-client";
import { useAppStore } from "@/store/app-store";
import { PageHeader } from "@/components/app/page-header";
import { StatCard } from "@/components/app/stat-card";
import { StatusBadge } from "@/components/app/status-badge";
import { EmptyState, LoadingState, ErrorState } from "@/components/app/empty-state";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { AlertCircle, Clock, FileText, Activity, MapPin, Calendar, ChevronRight, CheckCircle2, AlertTriangle, Briefcase, Users, LayoutDashboard, Truck, PieChartIcon, TrendingUp, Heart, Receipt } from "lucide-react";
import { formatDate, formatDateTime, formatMoney } from "@/lib/constants";
import { StatusPieChart } from "@/components/app/charts";
import { RecentActivity } from "@/components/app/recent-activity";
import { Badge } from "@/components/ui/badge";

interface CustomerRequest {
  requestId: string;
  status: string;
  origin?: { name: string };
  destination?: { name: string };
  scheduledDepartureDate: string;
}

interface CustomerHorse {
  horseId: string;
}

interface CustomerInvoice {
  invoiceId: string;
}

export function CustomerDashboard() {
  const { navigate } = useAppStore();
  const [requests, setRequests] = useState<CustomerRequest[]>([]);
  const [horseCount, setHorseCount] = useState(0);
  const [invoiceCount, setInvoiceCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    let active = true;
    Promise.all([
        apiGet<CustomerRequest[]>("/transport-requests/my"),
        apiGet<CustomerHorse[]>("/horses/my-horses"),
        apiGet<CustomerInvoice[]>("/my/invoices"),
      ])
      .then(([requestData, horseData, invoiceData]) => {
        if (!active) return;
        setRequests(requestData);
        setHorseCount(horseData.length);
        setInvoiceCount(invoiceData.length);
        setError("");
      })
      .catch((err: unknown) => {
        if (active) {
          setError(err instanceof Error ? err.message : "Không thể tải bảng điều khiển.");
        }
      })
      .finally(() => {
        if (active) setLoading(false);
      });

    return () => {
      active = false;
    };
  }, []);

  if (loading) return <LoadingState />;
  if (error) return <ErrorState message={error} />;

  return (
    <div className="space-y-6">
      <PageHeader
        title="Bảng điều khiển Khách hàng"
        description="Theo dõi hồ sơ ngựa, yêu cầu vận chuyển và hóa đơn của bạn"
        icon={<LayoutDashboard className="h-5 w-5" />}
        actions={
          <Button onClick={() => navigate("request-create")} className="gap-2 btn-press">
            <FileText className="h-4 w-4" /> Tạo yêu cầu
          </Button>
        }
      />

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
        <StatCard label="Hồ sơ ngựa" value={horseCount} icon={<Heart className="h-6 w-6" />} tone="info" />
        <StatCard label="Yêu cầu vận chuyển" value={requests.length} icon={<FileText className="h-6 w-6" />} tone="warning" />
        <StatCard label="Hóa đơn" value={invoiceCount} icon={<Receipt className="h-6 w-6" />} tone="success" />
      </div>

      <Card className="card-hover">
        <CardHeader>
          <CardTitle className="text-base">Yêu cầu vận chuyển gần đây</CardTitle>
        </CardHeader>
        <CardContent>
          {requests.length === 0 ? (
            <EmptyState
              icon={<FileText className="h-6 w-6" />}
              title="Chưa có yêu cầu vận chuyển"
              description="Tạo yêu cầu đầu tiên để bắt đầu theo dõi hành trình."
            />
          ) : (
            <div className="space-y-2">
              {requests.slice(0, 5).map((request) => (
                <button
                  key={request.requestId}
                  onClick={() => navigate("request-detail", { id: request.requestId })}
                  className="flex w-full items-center gap-4 rounded-lg border border-border bg-card p-3 text-left transition-all hover:border-primary/40 hover:shadow-sm"
                >
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-sm font-semibold">
                      Yêu cầu #{request.requestId.slice(-8).toUpperCase()}
                    </p>
                    <p className="mt-1 text-xs text-muted-foreground">
                      {request.origin?.name || "—"} → {request.destination?.name || "—"}
                      {" · "}
                      {formatDate(request.scheduledDepartureDate)}
                    </p>
                  </div>
                  <StatusBadge status={request.status} />
                </button>
              ))}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

export function ManagerDashboard() {
  const { navigate } = useAppStore();
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    (async () => {
      try {
        const d = await apiGet("/dashboard");
        setData(d);
      } catch (e: any) { setError(e.message); }
      finally { setLoading(false); }
    })();
  }, []);

  if (loading) return <LoadingState />;
  if (error) return <ErrorState message={error} />;

  const { stats, recentRequests, incidents, approvals } = data || {};

  return (
    <div className="space-y-6">
      <PageHeader
        title="Bảng điều khiển Quản lý"
        description="Tổng quan vận hành, phê duyệt yêu cầu và theo dõi sự cố"
        icon={<LayoutDashboard className="h-5 w-5" />}
        actions={
          <Button onClick={() => navigate("requests")} className="gap-2 btn-press">
            <Briefcase className="h-4 w-4" /> Quản lý tất cả đơn
          </Button>
        }
      />

      {/* Stats Overview */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <StatCard label="Tổng đơn (Tháng)" value={stats?.totalRequests || 0} icon={<FileText className="h-6 w-6" />} tone="info" delay={0} />
        <StatCard label="Chờ duyệt" value={stats?.pendingApprovals || 0} icon={<Clock className="h-6 w-6" />} tone="warning" delay={0.05} />
        <StatCard label="Đang di chuyển" value={stats?.activeTrips || 0} icon={<Truck className="h-6 w-6" />} tone="success" delay={0.1} />
        <StatCard label="Sự cố hằng ngày" value={stats?.dailyIncidents || 0} icon={<AlertTriangle className="h-6 w-6" />} tone="danger" delay={0.15} />
      </div>

      <div className="grid gap-6 lg:grid-cols-3">
        {/* Pending Approvals */}
        <Card className="lg:col-span-2 card-hover">
          <CardHeader className="flex flex-row items-center justify-between">
            <CardTitle className="text-base flex items-center gap-2"><CheckCircle2 className="h-4 w-4 text-warning" /> Yêu cầu chờ duyệt</CardTitle>
            <Button variant="ghost" size="sm" onClick={() => navigate("requests")} className="gap-1 text-muted-foreground">
              Xem tất cả <ChevronRight className="h-4 w-4" />
            </Button>
          </CardHeader>
          <CardContent>
            {(!approvals || approvals.length === 0) ? (
              <EmptyState icon={<CheckCircle2 className="h-6 w-6" />} title="Không có đơn chờ duyệt" description="Tất cả các yêu cầu đã được xử lý." />
            ) : (
              <div className="space-y-2">
                {approvals.map((r: any) => (
                  <button key={r.requestId} onClick={() => navigate("request-detail", { id: r.requestId })} className="flex w-full items-center gap-4 rounded-lg border border-border bg-card p-3 text-left transition-all hover:border-primary/40 hover:shadow-sm">
                    <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-warning/10 text-warning">
                      <Clock className="h-5 w-5" />
                    </div>
                    <div className="min-w-0 flex-1">
                      <p className="truncate text-sm font-semibold">{r.competitionName || `Đơn #${r.requestId.slice(-8).toUpperCase()}`}</p>
                      <div className="mt-0.5 flex flex-wrap items-center gap-x-3 gap-y-0.5 text-xs text-muted-foreground">
                        <span className="flex items-center gap-1 font-medium text-foreground">{r.customerName || "Khách hàng"}</span>
                        <span className="flex items-center gap-1"><MapPin className="h-3 w-3" />{r.origin?.name} → {r.destination?.name}</span>
                      </div>
                    </div>
                    <div className="flex flex-col items-end gap-1">
                      <StatusBadge status={r.status} />
                      <span className="text-xs text-muted-foreground">{formatDate(r.createdAt)}</span>
                    </div>
                  </button>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Charts */}
        <Card className="card-hover">
           <CardHeader><CardTitle className="flex items-center gap-2 text-base"><PieChartIcon className="h-4 w-4 text-primary" /> Phân bổ đơn hàng</CardTitle></CardHeader>
           <CardContent>
             {stats?.requestsByStatus ? <StatusPieChart data={stats.requestsByStatus} /> : <p className="text-sm text-muted-foreground text-center py-4">Chưa có dữ liệu</p>}
           </CardContent>
        </Card>
      </div>

      <div className="grid gap-6 lg:grid-cols-2">
         {/* Active Incidents */}
         <Card className="card-hover">
          <CardHeader className="flex flex-row items-center justify-between border-b pb-3">
            <CardTitle className="text-base flex items-center gap-2"><AlertTriangle className="h-4 w-4 text-danger" /> Sự cố cần lưu ý</CardTitle>
          </CardHeader>
          <CardContent className="pt-4">
            {(!incidents || incidents.length === 0) ? (
              <p className="py-4 text-center text-sm text-muted-foreground">Không có sự cố nào.</p>
            ) : (
              <div className="space-y-3">
                {incidents.map((inc: any) => (
                  <div key={inc.id} className="rounded-lg border border-danger/30 bg-danger/5 p-3">
                    <div className="flex justify-between items-start mb-1">
                      <p className="text-sm font-medium leading-tight">{inc.title}</p>
                      <Badge variant="destructive" className="text-[10px] uppercase">{inc.severity}</Badge>
                    </div>
                    <p className="text-xs text-muted-foreground line-clamp-2">{inc.description}</p>
                    <p className="mt-2 text-[10px] font-medium text-danger">{formatDateTime(inc.reportedAt)} - Chuyến xe #{inc.tripId?.slice(-6)}</p>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Recent Requests overview */}
        <Card className="card-hover">
          <CardHeader className="flex flex-row items-center justify-between border-b pb-3">
            <CardTitle className="text-base">Hoạt động gần đây</CardTitle>
          </CardHeader>
          <CardContent className="pt-0">
             <RecentActivity />
          </CardContent>
        </Card>
      </div>
    </div>
  );
}